secq6vgen_result *secq6vgens_answer(const secq6vgens_reading *r, int64_t p1, const uint8_t *p2, size_t p2__len, const uint8_t *p3, size_t p3__len);

/* Every kept version's state becomes invalid. */
void secq6vgens_invalidate_all(const secq6vgens_store *st);

/* How many versions are kept. */
size_t secq6vgens_version_count(const secq6vgens_store *st);

